public final class DBMSQLQueryStoreQueryHintAggViewBuilder extends DBMSQLObjects
{
    str     viewName;
    str     hintsViewName;
    str     asQueryId;
    str     asQueryHintText;
    str     asQueryHintHash;
    str     asRecId;
}

Method.Source:
protected boolean createViews()
{
    return this.dropView(viewName) && this.executeSqlStatementWithParameters(this.createViewSqlStmt(), SqlParams::create());
}

public static void main(Args args)
{
    var builder = DBMSQLQueryStoreQueryHintAggViewBuilder::construct();
    builder.createSqlObjects();
}

private str createViewSqlStmt()
{
    str sqlStmt = 'CREATE VIEW ' + viewName + ' AS ' + this.createSQLStatement();
    return sqlStmt;
}

private str createSQLStatement()
{
    str aggExpr = DBMSQLUtils::stringAgg('CONVERT([NVARCHAR](MAX), QueryHintText)', ' ', 'QueryHintId');
    str hashExpr = DBMSQLUtils::hashBytes('SHA2_256', aggExpr);

    str sqlStmt = strFmt(@"SELECT
        QueryId AS %1,
        %2 AS %3,
        %4 AS %5,
        1010 AS %6
        FROM %7
        GROUP BY QueryId",
        asQueryId,
        aggExpr,
        asQueryHintText,
        hashExpr,
        asQueryHintHash,
        asRecId,
        hintsViewName);

    return sqlStmt;
}

protected void initialize(boolean _runOnSeparateUserConnection = false)
{
    super(_runOnSeparateUserConnection);

    SysDictView view    = new SysDictView(tableNum(DBMSQLQueryStoreQueryHintAgg));
    viewName            = view.name(DbBackend::Sql);
    asQueryId           = view.fieldObject(fieldNum(DBMSQLQueryStoreQueryHintAgg, QueryId)).name(DbBackend::Sql);
    asQueryHintText     = view.fieldObject(fieldNum(DBMSQLQueryStoreQueryHintAgg, QueryHintText)).name(DbBackend::Sql);
    asQueryHintHash     = view.fieldObject(fieldNum(DBMSQLQueryStoreQueryHintAgg, QueryHintHash)).name(DbBackend::Sql);
    asRecId             = view.fieldObject(fieldNum(DBMSQLQueryStoreQueryHintAgg, RecId)).name(DbBackend::Sql);

    SysDictView hintsView = new SysDictView(tableNum(DBMSQLQueryStoreQueryHints));
    hintsViewName       = hintsView.name(DbBackend::Sql);
}

public static DBMSQLQueryStoreQueryHintAggViewBuilder construct()
{
    return new DBMSQLQueryStoreQueryHintAggViewBuilder();
}
